import os
import numpy as np


class Config:
    """
    Configuration parameters for the Kernel-Pooling Interaction Network pipeline.
    """

    # -------------------------------------------------------------------------
    # Directory and File Paths
    # -------------------------------------------------------------------------
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"
    WORKING_DIR = "./working/idea_8"
    SUBMISSION_DIR = "./submission"

    # Metadata Paths (Generated by previous steps)
    TRAIN_META_PATH = os.path.join(METADATA_DIR, "train_metadata.csv")
    VAL_META_PATH = os.path.join(METADATA_DIR, "validation_metadata.csv")
    TEST_META_PATH = os.path.join(METADATA_DIR, "test_metadata.csv")

    # Raw Data Paths
    TRAIN_DATA_PATH = os.path.join(INPUT_DIR, "simplified-nq-train.jsonl")
    TEST_DATA_PATH = os.path.join(INPUT_DIR, "simplified-nq-test.jsonl")
    SAMPLE_SUBMISSION_PATH = os.path.join(INPUT_DIR, "sample_submission.csv")

    # Output Paths
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # Cache Paths (for deterministic data processing)
    # Using .npy for numpy arrays and .parquet for dataframes
    VOCAB_CACHE_PATH = os.path.join(WORKING_DIR, "vocab.npy")
    EMBEDDING_MATRIX_CACHE_PATH = os.path.join(WORKING_DIR, "embedding_matrix.npy")

    # Feature Cache Paths
    TRAIN_FEATURES_PATH = os.path.join(WORKING_DIR, "train_features.parquet")
    VAL_FEATURES_PATH = os.path.join(WORKING_DIR, "val_features.parquet")
    TEST_FEATURES_PATH = os.path.join(WORKING_DIR, "test_features.parquet")

    # Model Checkpoint
    MODEL_CHECKPOINT_PATH = os.path.join(WORKING_DIR, "best_model.pth")

    # -------------------------------------------------------------------------
    # Data Processing Hyperparameters
    # -------------------------------------------------------------------------
    # Text Preprocessing
    MAX_QUESTION_LENGTH = 20
    MAX_CANDIDATE_LENGTH = 300
    VOCAB_SIZE = 100000  # Limit vocabulary size to keep model lightweight
    UNK_TOKEN = "<UNK>"
    PAD_TOKEN = "<PAD>"

    # Embedding Layer
    EMBEDDING_DIM = 300  # Standard dimension for GloVe or similar embeddings
    USE_PRETRAINED_EMBEDDINGS = False  # If False, learn embeddings from scratch

    # -------------------------------------------------------------------------
    # Model Architecture Hyperparameters
    # -------------------------------------------------------------------------
    # Kernel Pooling (Ranking Module)
    # RBF Kernels defined by Mean (mu) and Sigma (width)
    # Range covers [-1, 1] for Cosine Similarity
    # Kernel 1: Exact match (mu=1.0, sigma=0.001) - very sharp
    # Kernels 2-11: Soft matches (mu=0.9 down to -0.9, sigma=0.1) - wider
    KERNEL_MEANS = [1.0, 0.9, 0.7, 0.5, 0.3, 0.1, -0.1, -0.3, -0.5, -0.7, -0.9]
    KERNEL_SIGMAS = [0.001] + [0.1] * 10
    NUM_KERNELS = len(KERNEL_MEANS)

    # Span Prediction Module (Depthwise Separable Encoder)
    CONV_FILTERS = 128
    CONV_KERNEL_SIZE = 3
    ENCODER_LAYERS = 3
    HIDDEN_DIM = 128
    DROPOUT_RATE = 0.2

    # Yes/No Classification Head
    NUM_YES_NO_CLASSES = 3  # NONE, YES, NO

    # -------------------------------------------------------------------------
    # Training Hyperparameters
    # -------------------------------------------------------------------------
    SEED = 42
    BATCH_SIZE = 32
    LEARNING_RATE = 0.001
    EPOCHS = 5

    # Optimization
    EARLY_STOPPING_PATIENCE = 2  # Stop if validation loss doesn't improve for 2 epochs

    # Sampling Strategy
    # Ratio of negative candidates (non-answers) to positive candidates in a batch
    NEGATIVE_SAMPLES_RATIO = 4

    # Loss Weights (Multi-task learning)
    LOSS_WEIGHT_RANKING = 1.0
    LOSS_WEIGHT_SPAN = 1.0
    LOSS_WEIGHT_YESNO = 0.5

    # -------------------------------------------------------------------------
    # Inference Hyperparameters
    # -------------------------------------------------------------------------
    # Threshold for the Long Answer Score (0 to 1).
    # If max score < threshold, predict BLANK (no answer).
    LONG_ANSWER_THRESHOLD = 0.4

    def __init__(self):
        """
        Initialize configuration and ensure necessary directories exist.
        """
        # Ensure working directory exists for caching
        os.makedirs(self.WORKING_DIR, exist_ok=True)

        # Ensure submission directory exists
        os.makedirs(self.SUBMISSION_DIR, exist_ok=True)


# Create a global instance for easy import
config = Config()
